(function(){try{var a=typeof window<"u"?window:typeof global<"u"?global:typeof globalThis<"u"?globalThis:typeof self<"u"?self:{},n=new a.Error().stack;n&&(a._sentryDebugIds=a._sentryDebugIds||{},a._sentryDebugIds[n]="8b1937d2-57ee-4e28-9662-8ac0703cf454",a._sentryDebugIdIdentifier="sentry-dbid-8b1937d2-57ee-4e28-9662-8ac0703cf454")}catch{}})();var g={p3:"Pakikipagkapwa",p4:"Pagkakapantay-pantay",p2:"Paggalang",p1:"Mga prinsipyo ng maayos na pakikisalamuha:"},i={p1:"Inaasahang pag-uugali:",p2:"Tratuhin ang lahat ng kasapi nang may paggalang.",p3:"Malugod naming tinatanggap ang nakabubuo at makatutulong na puna.",p4:"Tungkol ito sa musika, kaya panatilihin nating tungkol lamang sa musika ang ating mga komento at nilalaman.",p5:"Tratuhin ang iba gaya ng nais mong pagtratuhin ka."},o="Kodigo ng Pag-uugali ng Komunidad",t={p1:"Mahal nating lahat ang musika! Gaya ng anumang komunidad, mayroon tayong patakaran sa asal upang mapanatili ang armonya at positibong samahan, at matiyak na komportable ang lahat dito. Bumuo tayo ng magiliw na kapaligirang nagbibigay-inspirasyon sa ating paglikha."},p={p1:"Hindi katanggap-tanggap na pag-uugali (maaari naming burahin ang iyong account nang walang paunang abiso):",p2:"Walang-galang o nakakasakit na pagtrato sa ating kapwa tagalikha.",p3:"Spam.",p4:"Pagbabahagi ng nilalamang sekswal.",p5:"Pagsusulat ng mga komentong sadyang nanglalait, nakakasakit, o nang-iinis sa sinumang miyembro ng komunidad."},s={p1:"Mga pampublikong hakbang:"},m={p1:"Mga dahilan para sa agarang pagbabawal:",p2:"Pagbabahagi ng anumang uri ng nilalamang sekswal (mga larawan, komento, atbp.).",p3:"Pagbabahagi ng nilalaman o paggawa ng mga komentong naghihikayat ng karahasan, rasismo, ksenopobya, homopobya, seksismo, atbp.",p4:"Pag-spam sa iba."},l={p1:"Iba pang uri ng hindi katanggap-tanggap na asal:",p2:"Mang-insulto o mag-post ng mapanghamak na komento tungkol sa sinumang miyembro ng komunidad:",p3:"Unang pagkakataon: ipagwawalang-bisa namin ang kakayahan mong magkomento hanggang sa may karagdagang abiso.",p4:"Ikalawang paglabag: permanente naming aalisin ang kakayahang magkomento, o tatanggalin ang iyong account.",p5:"Spam sa suporta:",p6:"Laging handang tumulong ang aming pangkat ng suporta, hangga’t magalang at tungkol lamang sa aming plataporma ang iyong mensahe sa amin. Ang walang-galang o asal na parang spam ay hindi tinatanggap at maaaring humantong sa pagbura ng iyong account."},k={p1:"Ano ang itinuturing na walang-galang na komento?",p2:"Ang ganitong uri ng komento ay kadalasang walang kaugnayan, hindi angkop, nakasasama, o basta nakakainis. Hindi ito isinusulat nang may mabuting hangarin, at nilalayong magpasama ng loob o mapahiya ang iba.",p3:"Kung hindi ka sigurado kung walang-galang ang iyong komento, huwag mo na itong i-post at maghanap ng magalang at sibilisadong paraan ng pagpapahayag."},r={s2:g,s3:i,title:o,s1:t,s4:p,s5:s,s6:m,s7:l,s8:k};export{r as default,t as s1,g as s2,i as s3,p as s4,s as s5,m as s6,l as s7,k as s8,o as title};

